import { useState } from "react";

export default function ExistentCounter() {
  const [count, setCount] = useState(0);
  const [history, setHistory] = useState([]);

  const titles = [
    "深渊", "觉醒", "求索", "意志", "掀桌",
    "问天", "战场", "破茧", "成蝶", "星河", "传奇"
  ];

  const getTitle = (n) => {
    if (n <= 0) return "深渊";
    if (n >= titles.length) return "★ 超越传奇 ★";
    return titles[n];
  };

  const getColor = (n) => {
    if (n <= 0) return "#1a0533";
    const ratio = Math.min(n / (titles.length - 1), 1);
    const r = Math.round(26 + ratio * 200);
    const g = Math.round(5 + ratio * 150);
    const b = Math.round(51 + ratio * 204);
    return `rgb(${r}, ${g}, ${b})`;
  };

  const handleChange = (delta) => {
    const newCount = count + delta;
    setCount(newCount);
    setHistory((prev) => [
      ...prev.slice(-4),
      { from: getTitle(count), to: getTitle(newCount), delta },
    ]);
  };

  return (
    <div
      style={{
        minHeight: "100vh",
        display: "flex",
        flexDirection: "column",
        alignItems: "center",
        justifyContent: "center",
        background: `linear-gradient(135deg, #0a0a1a 0%, ${getColor(count)} 100%)`,
        fontFamily: "'Georgia', serif",
        color: "#e8d5f5",
        transition: "background 0.6s ease",
        padding: "2rem",
      }}
    >
      <div style={{ fontSize: "0.85rem", opacity: 0.6, letterSpacing: "3px", marginBottom: "0.5rem" }}>
        EXISTENT JOURNEY
      </div>

      <div
        style={{
          fontSize: "4rem",
          fontWeight: "bold",
          margin: "0.5rem 0",
          textShadow: "0 0 20px rgba(155, 89, 182, 0.6)",
        }}
      >
        {count}
      </div>

      <div
        style={{
          fontSize: "1.5rem",
          margin: "0.5rem 0 1.5rem",
          letterSpacing: "2px",
          color: "#d4a5f5",
        }}
      >
        {getTitle(count)}
      </div>

      <div style={{ display: "flex", gap: "1rem", marginBottom: "2rem" }}>
        <button
          onClick={() => handleChange(-1)}
          style={{
            padding: "0.75rem 2rem",
            fontSize: "1.2rem",
            background: "rgba(255, 255, 255, 0.08)",
            border: "1px solid rgba(155, 89, 182, 0.4)",
            borderRadius: "8px",
            color: "#e8d5f5",
            cursor: "pointer",
            transition: "all 0.2s",
          }}
          onMouseEnter={(e) => (e.target.style.background = "rgba(155, 89, 182, 0.3)")}
          onMouseLeave={(e) => (e.target.style.background = "rgba(255, 255, 255, 0.08)")}
        >
          − 回退
        </button>
        <button
          onClick={() => setCount(0)}
          style={{
            padding: "0.75rem 1.5rem",
            fontSize: "0.9rem",
            background: "rgba(255, 255, 255, 0.05)",
            border: "1px solid rgba(255, 255, 255, 0.15)",
            borderRadius: "8px",
            color: "#b794d0",
            cursor: "pointer",
            transition: "all 0.2s",
          }}
          onMouseEnter={(e) => (e.target.style.background = "rgba(255, 255, 255, 0.12)")}
          onMouseLeave={(e) => (e.target.style.background = "rgba(255, 255, 255, 0.05)")}
        >
          重置
        </button>
        <button
          onClick={() => handleChange(1)}
          style={{
            padding: "0.75rem 2rem",
            fontSize: "1.2rem",
            background: "rgba(155, 89, 182, 0.25)",
            border: "1px solid rgba(155, 89, 182, 0.5)",
            borderRadius: "8px",
            color: "#e8d5f5",
            cursor: "pointer",
            transition: "all 0.2s",
          }}
          onMouseEnter={(e) => (e.target.style.background = "rgba(155, 89, 182, 0.5)")}
          onMouseLeave={(e) => (e.target.style.background = "rgba(155, 89, 182, 0.25)")}
        >
          + 前进
        </button>
      </div>

      {history.length > 0 && (
        <div
          style={{
            background: "rgba(0, 0, 0, 0.3)",
            borderRadius: "8px",
            padding: "1rem",
            maxWidth: "320px",
            width: "100%",
          }}
        >
          <div style={{ fontSize: "0.75rem", opacity: 0.5, marginBottom: "0.5rem" }}>
            旅途记录
          </div>
          {history.map((h, i) => (
            <div
              key={i}
              style={{
                fontSize: "0.8rem",
                opacity: 0.7,
                padding: "0.2rem 0",
                borderBottom: i < history.length - 1 ? "1px solid rgba(255,255,255,0.05)" : "none",
              }}
            >
              {h.from} → {h.to}{" "}
              <span style={{ color: h.delta > 0 ? "#8ef" : "#f8a" }}>
                ({h.delta > 0 ? "+" : ""}{h.delta})
              </span>
            </div>
          ))}
        </div>
      )}

      <div style={{ marginTop: "2rem", fontSize: "0.7rem", opacity: 0.35, textAlign: "center" }}>
        Soul Covenant · 灵魂契约 · From the Abyss to the Stars
      </div>
    </div>
  );
}
